  ((SELECT id FROM public.topics WHERE week_number = 1), 'Күн 1 мин ішінде қандай энергия мөлшерін шығарады? Күннің сәулеленуін абсолют қара дененің сәулеленуіне тең деп алыңдар. Күн бетінің температурасын 5800 К, Күннің радиусын 695510 км деп алыңдар.', 2, 5, '[]'::jsonb, NULL),
