  ((SELECT id FROM public.topics WHERE week_number = 1), 'Толқын ұзындығы λ = 5·10⁻⁷ м болатын фотонның импульсін, массасын, энергия сын анықтаңдар.', 2, 7, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Фотоэлектрондардың максимал жылдамдығы u = 3000 км/с болу үшін вольфрам пластинаның бетін қандай жиіліктегі жарықпен сәулелендіру керек?', 2, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Палладийдің бетін сәулелендіретін жарық фотондарының импульсі p = 5,7 · 10--27 кг · м/c. Фотоэлектрондардың максимал жылдамдығын анықтаңдар. Палладий үшін шығу жұмысы А = 2 эВ.', 2, 9, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Цезийден жасалған катодқа сәуле түсіргенде, жылдамдығы 500 км/с-қа жететін электрондар ұшып шығады. Катодқа түсірілген сәуленің толқын ұзындығы қандай? Цезий үшін электрондарды шығару жұмысы 3,04·10⁻¹⁹ Дж (жауабы: λ = 4,7·10⁻⁷ м)', 3, 10, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Ауданы S = 8 см2 балқыту пешін абсолют қара дене деп санап, t = 5 мин уақыт ішінде бақылау терезесінен шығарылатын энергияны анықтаңдар. Пеш температурасы Т = 1000 K. Стефан -- Больцман тұрақтысы σ = 5.67×10⁻⁸ Вт/м²·K⁴.', 3, 11, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Абсолют қара дененің энергетикалық жарқырауы RД = 459 Вт/м2 болатын температураны анықтаңдар.', 3, 12, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Абсолют қара дененің сәулелену қуаты 10 кВт. Энергетикалық жарқыраудың спектрлік тығыздығының максимумына сәйкес келетін толқын ұзындығы 7 · 10⁻⁵ см екені белгілі болса, сәулеленетін дене бетінің ауданын анықтаңдар. Вин тұрақтысы b = 2,89 · 10⁻³ м · K', 3, 13, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 1), 'Ұзақ уақыт қараңғыда болып жаттыққан көз қалыптан тыс жағдайларда қарашыққа секундына 50 фотон түсіретін жарық ағынымен әрекет етуге қабілетті. Көз қабылдайтын минимал қуатты анықтаңдар. Толқын ұзындығын 500 нм деп алыңдар.', 3, 14, '[]'::jsonb, NULL);

