INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Де Бройль гипотезасы. Томсон,Резерфорд моделдері.Бор постулаты', 1, 0, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электрон жылдамдығы $v = 2 \times 10^{6}$м/с. Электрон массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Де Бройль толқын ұзындығын табыңдар.', 1, 1, '["Де Бройль формуласы:","$$\\lambda = \\frac{h}{mv}$$","мұндағы $h = 6,626 \\times 10^{- 34}$Дж·с.","$$\\lambda = \\frac{6,626 \\times 10^{- 34}}{9,11 \\times 10^{- 31} \\times 2 \\times 10^{6}} \\approx 3,64 \\times 10^{- 10}\\text{ м}$$"]', '$\lambda \approx 0,364\text{ нм}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Атомдағы электрон саны $Z = 3$(Li атомы). Әр электронның заряды $e = 1,6 \times 10^{- 19}$Кл. Атомдағы жалпы электрондық зарядты табыңдар.', 1, 2, '["$$Q = Z \\times e = 3 \\times 1,6 \\times 10^{- 19} = 4,8 \\times 10^{- 19}\\text{ Кл}$$"]', '$Q = 4,8 \times 10^{- 19}$Кл'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Атом ядросының радиусы $R = 1,2 \times 10^{- 15} \times A^{1/3}$м, мұндағы $A = 4$(гелий). Ядро радиусын есептеңдер.', 1, 3, '["$$R = 1,2 \\times 10^{- 15} \\times 4^{1/3} \\approx 1,9 \\times 10^{- 15}\\text{ м}$$"]', '$R \approx 1,9\text{ фм}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Бор моделі бойынша электронның бірінші орбитасының радиусы $r_{1} = 5,29 \times 10^{- 11}$м. Электронның массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Электронның бірінші орбитадағы импульсін табыңдар.', 1, 4, '["Бор постулаты бойынша электрон импульсі:","$${L = mvr = n\\frac{h}{2\\pi},n = 1 }{L = \\frac{6,626 \\times 10^{- 34}}{2\\pi} \\approx 1,055 \\times 10^{- 34}\\text{ кг х м/с} }$$"]', '$L \approx 1,055 \times 10^{- 34}\text{ кг х м/с}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Протон массасы $m_{p} = 1,67 \times 10^{- 27}$кг, жылдамдығы $v = 1 \times 10^{5}$м/с. Де Бройль толқын ұзындығын табыңдар.', 1, 5, '["$$\\lambda = \\frac{h}{mv} = \\frac{6,626 \\times 10^{- 34}}{1,67 \\times 10^{- 27} \\times 1 \\times 10^{5}} \\approx 3,97 \\times 10^{- 12}\\text{ м}$$"]', '$\lambda \approx 3,97\text{ пм}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электронның кинетикалық энергиясы $K = 1,5 \times 10^{- 17}$Дж. Электрон массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Де Бройль толқын ұзындығын табыңдар.', 2, 6, '["Кинетикалық энергия:","$${K = \\frac{1}{2}mv^{2}\\text{\\:\\,} \\Longrightarrow \\text{\\:\\,}v = \\sqrt{\\frac{2K}{m}} }{v = \\sqrt{\\frac{2 \\times 1,5 \\times 10^{- 17}}{9,11 \\times 10^{- 31}}} \\approx 1,81 \\times 10^{7}\\text{ м/с} }$$","Де Бройль формуласы:","$$\\lambda = \\frac{h}{mv} = \\frac{6,626 \\times 10^{- 34}}{9,11 \\times 10^{- 31} \\times 1,81 \\times 10^{7}} \\approx 4,03 \\times 10^{- 11}\\text{ м}$$"]', '$\lambda \approx 0,0403\text{ нм}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Атомдағы электрон саны $Z = 11$(Na атомы). Электрондардың жалпы массасы атом массасының 0,05%-ын құрайды. Атом массасы $M = 3,82 \times 10^{- 26}$кг. Электрондардың массалық үлесін тексеріңдер.', 2, 7, '["Электрондардың массасы:","$$m_{e} = 9,11 \\times 10^{- 31}\\text{ кг},M_{e} = Z \\times m_{e} = 11 \\times 9,11 \\times 10^{- 31} \\approx 1,002 \\times 10^{- 29}\\text{ кг}$$","Массалық үлесі:","$$\\frac{M_{e}}{M} \\times 100\\% = \\frac{1,002 \\times 10^{- 29}}{3,82 \\times 10^{- 26}} \\times 100\\% \\approx 0,026\\%$$"]', '$\approx 0,026\%$(шамамен 0,05% дегенге жақын)'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Альфа бөлшектері арқылы өткізілген тәжірибе нәтижесінде ядро заряды $Z = 79$(Au). Электрлік күш арқылы бөлшектің ең жақын келу радиусын $r_{\min}$табыңдар, егер кинетикалық энергия $K = 5,0 \times 10^{- 13}$Дж.', 2, 8, '["Екі заряд арасындағы электрлік потенциал:","$${K = \\frac{1}{4\\pi\\varepsilon_{0}}\\frac{Z_{1}Z_{2}e^{2}}{r_{\\min}} }{r_{\\min} = \\frac{1}{4\\pi\\varepsilon_{0}}\\frac{Z_{1}Z_{2}e^{2}}{K} }$$","мұндағы $Z_{1} = 2$(α-бөлшек), $Z_{2} = 79$, $e = 1,6 \\times 10^{- 19}$Кл, $\\frac{1}{4\\pi\\varepsilon_{0}} = 9 \\times 10^{9}\\text{ Н\\textbackslash cdotpм²/Кл²}$","$$r_{\\min} = \\frac{9 \\times 10^{9} \\times 2 \\times 79 \\times (1,6 \\times 10^{- 19})^{2}}{5,0 \\times 10^{- 13}} \\approx 7,26 \\times 10^{- 14}\\text{ м}$$"]', '$r_{\min} \approx 7,26 \times 10^{- 14}$м'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электрон $n = 2$орбитада, $r_{2} = 2,12 \times 10^{- 10}$м. Электрон массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Бор постулаты бойынша электронның жылдамдығын табыңдар.', 2, 9, '["Бор импульс шарты:","$${mvr = n\\frac{h}{2\\pi}\\text{\\:\\,} \\Longrightarrow \\text{\\:\\,}v = \\frac{nh}{2\\pi mr} }{v = \\frac{2 \\times 6,626 \\times 10^{- 34}}{2\\pi \\times 9,11 \\times 10^{- 31} \\times 2,12 \\times 10^{- 10}} \\approx 1,03 \\times 10^{6}\\text{ м/с} }$$"]', '$v \approx 1,03 \times 10^{6}$м/с'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электронның толқын ұзындығы $\lambda = 5 \times 10^{- 11}$м, массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Электронның жылдамдығын табыңдар.', 2, 10, '["$${\\lambda = \\frac{h}{mv}\\text{\\:\\,} \\Longrightarrow \\text{\\:\\,}v = \\frac{h}{m\\lambda} }{v = \\frac{6,626 \\times 10^{- 34}}{9,11 \\times 10^{- 31} \\times 5 \\times 10^{- 11}} \\approx 1,45 \\times 10^{7}\\text{ м/с} }$$"]', '$v \approx 1,45 \times 10^{7}$м/с'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электрон кинетикалық энергиясы $K = 2 \times 10^{- 17}$Дж. Де Бройль толқын ұзындығын есептеңдер. Содан кейін электронның Бор моделіндегі қандай орбитада орналасуы мүмкін екенін анықтаңдар (1-ден 3-ге дейінгі орбиталарда).', 3, 11, '["Жылдамдық:","$$v = \\sqrt{\\frac{2K}{m_{e}}} = \\sqrt{\\frac{2 \\times 2 \\times 10^{- 17}}{9,11 \\times 10^{- 31}}} \\approx 2,09 \\times 10^{7}\\text{ м/с}$$","Де Бройль толқын ұзындығы:","$$\\lambda = \\frac{h}{mv} = \\frac{6,626 \\times 10^{- 34}}{9,11 \\times 10^{- 31} \\times 2,09 \\times 10^{7}} \\approx 3,48 \\times 10^{- 11}\\text{ м}$$","Бор орбитасының радиустары:","$${r_{n} = n^{2} \\times 5,29 \\times 10^{- 11}\\text{ м},n = 1,2,3 }{r_{1} = 5,29 \\times 10^{- 11}\\text{ м},\\text{ }r_{2} = 2,12 \\times 10^{- 10}\\text{ м},\\text{ }r_{3} = 4,76 \\times 10^{- 10}\\text{ м} }$$","$\\lambda\\$ең жақын қандай орбитаның радиусына сәйкес келеді:","$\\lambda \\approx 3,48 \\times 10^{- 11}$м → n = 1 орбитасы"]', '$\lambda \approx 3,48 \times 10^{- 11}$м, электрон 1-орбитада орналасуы мүмкін'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Альфа бөлшектері алтын парақ арқылы өтеді. Кинетикалық энергиясы $K = 6 \times 10^{- 13}$Дж. Ядро заряды $Z = 79$. Бөлшектің ең жақын келу радиусын табыңдар. Содан кейін осы ядроның зарядын Бор моделі бойынша электрондардың бірінші орбитасымен салыстырыңдар.', 3, 12, '["Ең жақын келу радиусы:","$$r_{\\min} = \\frac{1}{4\\pi\\varepsilon_{0}}\\frac{Z_{1}Z_{2}e^{2}}{K} = \\frac{9 \\times 10^{9} \\times 2 \\times 79 \\times (1,6 \\times 10^{- 19})^{2}}{6 \\times 10^{- 13}} \\approx 6,07 \\times 10^{- 14}\\text{ м}$$","Бор моделі бойынша 1-орбитадағы электрон импульсі:","$$L = \\frac{h}{2\\pi} \\approx 1,055 \\times 10^{- 34}\\text{ кг х м/с}$$","Ядро заряды $Z = 79$, электрон зарядымен салыстырсақ, ядро 79 электрондық зарядқа тең"]', '$r_{\min} \approx 6,07 \times 10^{- 14}$м, ядро зарядын 1-орбита электрон зарядымен салыстыру → 79e'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электрон Бордың $n = 3 \rightarrow n = 2$энергетикалық деңгейіне өтеді. Шыққан фотон энергиясын есептеңдер. Содан кейін электронның кинетикалық энергиясын Де Бройль формуласы арқылы есептеңдер.', 3, 13, '["Энергия деңгейлері:","$${E_{n} = - \\frac{13,6}{n^{2}}\\text{ эВ} }{E_{3} = - 1,51\\text{ эВ},E_{2} = - 3,4\\text{ эВ} }$$","Энергия айырмасы:","$$\\Delta E = E_{2} - E_{3} = - 3,4 - ( - 1,51) = - 1,89\\text{ эВ} \\approx 3,03 \\times 10^{- 19}\\text{ Дж}$$","Фотон толқын ұзындығы:","$$\\lambda = \\frac{hc}{\\Delta E} = \\frac{6,626 \\times 10^{- 34} \\times 3 \\times 10^{8}}{3,03 \\times 10^{- 19}} \\approx 6,56 \\times 10^{- 7}\\text{ м}$$","Де Бройль бойынша электрон жылдамдығы:","$$K = \\Delta E = \\frac{1}{2}mv^{2}\\text{\\:\\,} \\Longrightarrow \\text{\\:\\,}v = \\sqrt{\\frac{2K}{m}} = \\sqrt{\\frac{2 \\times 3,03 \\times 10^{- 19}}{9,11 \\times 10^{- 31}}} \\approx 8,15 \\times 10^{5}\\text{ м/с}$$"]', '$\lambda \approx 656\text{ нм},v \approx 8,15 \times 10^{5}\text{ м/с}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Электрон $n = 4$орбитада, массасы $m_{e} = 9,11 \times 10^{- 31}$кг. Жылдамдығын Бор постулаты арқылы есептеңдер, содан кейін Де Бройль толқын ұзындығын анықтаңдар.', 3, 14, '["Бор импульсі:","$${mvr = n\\frac{h}{2\\pi}\\text{\\:\\,} \\Longrightarrow \\text{\\:\\,}v = \\frac{nh}{2\\pi mr} }{r_{4} = 4^{2} \\times 5,29 \\times 10^{- 11} = 8,46 \\times 10^{- 10}\\text{ м} }{v = \\frac{4 \\times 6,626 \\times 10^{- 34}}{2\\pi \\times 9,11 \\times 10^{- 31} \\times 8,46 \\times 10^{- 10}} \\approx 5,45 \\times 10^{5}\\text{ м/с} }$$","Де Бройль толқын ұзындығы:","$$\\lambda = \\frac{h}{mv} = \\frac{6,626 \\times 10^{- 34}}{9,11 \\times 10^{- 31} \\times 5,45 \\times 10^{5}} \\approx 1,33 \\times 10^{- 9}\\text{ м}$$"]', '$v \approx 5,45 \times 10^{5}$м/с, $\lambda \approx 1,33\text{ нм}$'),
  ((SELECT id FROM public.topics WHERE week_number = 2), 'Протон кинетикалық энергиясы $K = 1 \times 10^{- 16}$Дж. Де Бройль толқын ұзындығын табыңдар. Протон алтын ядросына ең жақын келгенде (Резерфорд тәжірибесі), рентген фотон энергиясын есептеңдер, егер энергия толық фотоны береді деп есептелсін.', 3, 15, '["Протон жылдамдығы:","$$v = \\sqrt{\\frac{2K}{m_{p}}} = \\sqrt{\\frac{2 \\times 1 \\times 10^{- 16}}{1,67 \\times 10^{- 27}}} \\approx 3,46 \\times 10^{5}\\text{ м/с}$$","Де Бройль толқын ұзындығы:","$$\\lambda = \\frac{h}{mv} = \\frac{6,626 \\times 10^{- 34}}{1,67 \\times 10^{- 27} \\times 3,46 \\times 10^{5}} \\approx 1,15 \\times 10^{- 11}\\text{ м}$$","Ең жақын келу кезінде кинетикалық энергия фотонға өтсе:","$$E = K = 1 \\times 10^{- 16}\\text{ Дж\\:\\,} \\Longrightarrow \\text{\\:\\,}\\lambda_{photon} = \\frac{hc}{E} = \\frac{6,626 \\times 10^{- 34} \\times 3 \\times 10^{8}}{1 \\times 10^{- 16}} \\approx 1,99 \\times 10^{- 9}\\text{ м}$$"]', '$\lambda_{proton} \approx 1,15 \times 10^{- 11}$м, $\lambda_{photon} \approx 1,99\text{ нм}$');

