INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Төртінші орбитадан екіншіге ауысқандағы сутек атомы шығаратын сәуленің толқын ұзындығы', 1, 0, '["$\\frac{1}{\\lambda}$​=R($\\frac{1}{2^{2}}$−​$\\frac{1}{4^{2}}$)=R($\\frac{1}{4}$​-$\\frac{1}{16}$)","λ=$\\frac{1}{2056454.625\\ }$м≈4.862726×10^-7^ м.","λ≈486.27 нм.","[Жауабы:485нм]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Үшінші орбитадан екіншіге ауысқандағы сутек атомы шығаратын сәуленің толқын ұзындығы', 1, 1, '["> $\\frac{1}{\\lambda}$​=R($\\frac{1}{2^{2}}$−​$\\frac{1}{3^{2}}$)=R($\\frac{1}{4}$​-$\\frac{1}{9}$)","$\\frac{1}{\\lambda}$= 1,0967758×10^7^×0.1388889=1.524×10^6^ м−1","λ=656 нм","[Жауабы:658нм]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Төртінші орбитадан үшіншіге ауысқандағы сутек атомы шығаратын сәуленің толқын ұзындығы', 1, 2, '["​$\\frac{1}{\\lambda}$​=1,0967758×10^7^($\\frac{1}{3^{2}}$−​$\\frac{1}{4^{2}}$​)","λ=$\\frac{1}{{5.325 \\times 10}^{5}}$=1.879×10^-6^ м","[Жауабы:1,88мкм]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Электрон 3-деңгейдіен 2-деңгейдіге түседі (сутек). Осы транзишннің толқын ұзындығын (нм), жиілігін (Гц) және фотон энергиясын (эВ) есептеңдер. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{2^{2}}$−​$\frac{1}{3^{2}}$)=R($\frac{1}{4}$​-$\frac{1}{9}$) λ=656.47 нм. Жиілік ν=$\frac{с}{\lambda}$=$\frac{{2.99792458 \times 10}^{8}}{{6.56469627 \times 10}^{7}}\$​≈4.56673768×10^14^ Гц. Фотон энергиясы E=hν=6.62607015×10^-34^×4.56673768×10^14^≈3.02595242×10^-19^ Дж. [Жауап: λ≈656.47нм, ν≈4.57×10^14^ Гц, E≈1.89 эВ.]{.mark}', 1, 3, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Электрон 4-деңгейдіен 2-деңгейдіге түседі (сутек). Осы транзишннің толқын ұзындығын (нм), жиілігін (Гц) және фотон энергиясын (эВ) есептеңдер. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{2^{2}}$−​$\frac{1}{4^{2}}$)=R($\frac{1}{4}$​-$\frac{1}{16}$) λ=486.27 нм Жиілік ν=$\frac{с}{\lambda}$=$\frac{{2.99792458 \times 10}^{8}}{486.27\ нм}\$​≈6.1651×10^14^ Гц. Фотон энергиясы E=hν=6.62607015×10^-34^×6.1651×10^14^ ≈2.55 эВ. [Жауабы: λ≈ 486.27 нм, ν≈ 6.1651×10^14^ Гц, E≈ 2.55 эВ.]{.mark}', 1, 4, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Электрон 2-деңгейдіен 1-деңгейдіге түседі (сутек). Осы транзишннің толқын ұзындығын (нм) және фотон энергиясын (эВ) есептеңдер. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{1^{2}}$−​$\frac{1}{2^{2}}$)=R($\frac{1}{1}$​-$\frac{1}{4}$) λ=121.57 нм, Фотон энергиясы E=$\frac{hc}{\lambda}$=6.62607015×10^-34^×$\frac{3 \times 10^{8}}{121.57 \times 10^{- 9}}$≈10.20 эВ. [Жауабы: λ≈ 121.57 нм, E≈ 10.20 эВ.]{.mark}', 2, 5, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Электрон 4-деңгейдіен 3-деңгейдіге түседі (сутек). Осы транзишннің толқын ұзындығын (нм) және фотон энергиясын (эВ) есептеңдер. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{3^{2}}$−​$\frac{1}{4^{2}}$)=R($\frac{1}{9}$​-$\frac{1}{16}$) λ=1876 нм Фотон энергиясы E=$\frac{hc}{\lambda}$=6.62607015×10^-34^×$\frac{3 \times 10^{8}}{1876\ \times 10^{- 9}}$≈0.66 эВ. [Жауабы: λ≈ 1876 нм, E≈ 0.66 эВ.]{.mark}', 2, 6, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Сутектің Бальмер сериясындағы n=5→2 сызығының толқын ұзындығын және қандай түске сәйкес келетінін анықтаңдар. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{2^{2}}$−​$\frac{1}{5^{2}}$)=R($\frac{1}{4}$-$\frac{1}{25}$) λ=434,17 нм Түс: көгілдір-күлгін Серия: Бальмер сериясы (көрінетін аймақ) [Жауабы: λ≈ 434.17нм, Бальмер сериясы]{.mark}', 2, 7, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Электрон 5-деңгейдіен 2-деңгейдіге түседі (сутек). Осы транзишннің толқын ұзындығын (нм), жиілігін (Гц) және фотон энергиясын (эВ) есептеңдер. Толқын ұзындығы $\frac{1}{\lambda}$​=R($\frac{1}{2^{2}}$−​$\frac{1}{5^{2}}$)=R($\frac{1}{4}$​-$\frac{1}{25}$) λ=434.17 нм Жиілік ν=$\frac{с}{\lambda}$=$\frac{{2.99792458 \times 10}^{8}}{434.17\ нм}\$​≈6.90×10^14^ Гц. Фотон энергиясы E=hν=6.62607015×10^-34^×6.90×10^14^ ≈2.856 эВ. [Жауабы: λ≈ 434.17 нм, ν≈ 6.90×10^14^ Гц, E≈ 2.856эВ.]{.mark}', 2, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Сутек атомындағы электрон 3-деңгейден 1-деңгейге өтеді.', 2, 9, '["а) Толқын ұзындығы","б) Жиілігі","в) Фотон энергиясы","а) Толқын ұзындығы","$\\frac{1}{\\lambda}$​=R($\\frac{1}{1^{2}}$−​$\\frac{1}{3^{2}}$)=R($\\frac{1}{1}$​-$\\frac{1}{9}$)","λ=102.5нм","б) Жиілігі","ν=$\\frac{с}{\\lambda}$=$\\frac{{2.99792458 \\times 10}^{8}}{102.5нм}\\$​≈2,93×10^15^  Гц.","в) Фотон энергиясы","E=hν=6.62607015×10^-34^×2,93×10^15^ ≈12.1 эВ.","[Жауабы: λ≈ 102.5нм, ν≈ 2,93×10^15^ Гц, E≈ 12.1 Эв]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Лайман-α сызығының тыныш күйдегі (эмиссиядағы) толқын ұзындығы шамамен 121.57 нм. Егер осы сызық спектрде 122.80 нм ретінде байқалса, спектр қалыпты жағдайға қарағанда қызылға ығысқан --- жұлдыздың радиалды жылдамдығын (нөлдік салыстырмалы жылдамдықпен) есептеңдер (паразиттік жылдамдықтың белгісі) --- жай доплер формуласы пайдаланыңыз (нөлге жуық жылдамдыққа арналған, 𝑣≪𝑐)', 3, 10, '["$\\frac{\\mathrm{\\Delta}\\lambda}{\\lambda_{0}}$=$\\frac{\\vartheta}{c}$",">","$$\\mathrm{\\Delta}\\lambda = 122.80 - 121.57 = 1.23нм$$",">",">","$$\\vartheta = с\\frac{\\mathrm{\\Delta}\\lambda}{\\lambda_{0}} = 3,03 \\bullet 10^{6}м/с$$","[Жауабы:]{.mark}$\\ \\vartheta = 3,03 \\bullet 10^{6}м/с$"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Салыстыр: (A) n=4→2 (Бальмер) және (B) n=5→3 (Пашен) транзишндерінің фотон энергиялары. Қайсысының энергиясы үлкен және қанша есе?', 3, 11, '["(А) үшін","4→2: λ≈486.27 нм⇒E~А~≈2.55 эВ.","(В) үшін","5→3: λ≈1282.2 нм⇒E~В~≈0.967 эВ.","Энергиялардың қатынасы:","$$\\ \\ \\ \\ \\ \\ \\ \\ \\ \\ \\ \\ \\ \\frac{Е_{А}}{Е_{В}} = \\frac{2.55}{0.967} = 2.64$$","[Жауабы:2,64]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Спектрде λ=1282.2 нм (инфрақызыл) сызығы табылды. Бұл Пашен сериясына тән пе және егер иә болса --- ол қандай транзишн (n→3)?', 3, 12, '["Пашен сериясы үшін","$\\frac{1}{\\lambda}$​=R($\\frac{1}{3^{2}}$−​$\\frac{1}{n^{2}}$)","n^2^≈25 → n≈5.","[Жауабы: n≈5.]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Балмер сериясындағы екі өтпеудің (n=5→2 және n=4→2) фотон энергияларын салыстыр және қайсысы қай түске сәйкес келетінін анықта.', 3, 13, '["𝝀~5-2~ ​≈4.340470×10^-7^ м=434.04 нм.","E~5-2~ ≈2.857 эВ.","𝝀~4-2~ ​≈ 4.85965×10^-7^ м=485.9 нм","E~4-2~ ≈ 2.551 эВ","[Жауабы:(n=5→2) E~5-2~ энергиясының шамасы үлкен]{.mark}","[Оның толқын ұзындығы 434нм болғандықтан, ол көрінетін жарыққа (сары-жасыл түске) жатады]{.mark}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 3), 'Салыстырыңдар: Лайман сериясының n=2→1 өтпесі мен Балмер сериясының n=3→2 өтпесі қайсысы энергиясы үлкен?', 3, 14, '["E2→1​≈10.2 эВ, ал E3→2≈1.89 эВ","$$\\frac{E_{Лайман}}{E_{Бальмер}} = \\frac{108}{20} = 5,4$$","[Жауабы:Екі энергия қатынасы 5,4-ті береді]{.mark}"]', NULL);

