  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 10 элементтің электрондық конфигурациясын жаз.', 1, 4, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 11 элементтің электрондары қабаттар бойынша қалай бөлінеді?', 1, 5, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 12 элементтің электрондық конфигурациясын және қабаттардағы бөлінуін көрсет.', 1, 6, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 16 элемент үшін электрондардың қабаттардағы үлестірілуін тап.', 1, 7, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 18 элементтің электрондық конфигурациясын және қабаттардағы санын жаз.', 1, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Сутек (H) пен литий (Li) атомдарының электрондық конфигурациясын жазып, салыстыр. → Қайсысы сілтілік металл екенін анықта.', 1, 9, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Натрий атомының (Z=11) электрондық конфигурациясын жазып, қай қабатта соңғы электрон орналасқанын көрсет.', 1, 10, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 20 (Ca). Электрондық конфигурациясын жазыңдар, қабаттар бойынша бөлінісін көрсетіңдер, қай период пен топта орналасқанын анықтаңдар және валентті электрон санын тап.', 2, 11, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Элементтің электрондық конфигурациясы: 1s² 2s² 2p⁶ 3s² 3p¹. Элементті анықтаңдар, оның период пен тобын тапңдар, сыртқы қабаттағы электрон санын көрсетіңдер.', 2, 12, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрондық конфигурация: 1s² 2s² 2p⁶ 3s² 3p⁴. Элементті анықтап, қабаттар бойынша бөліністі, период пен қасиетін сипатта.', 2, 13, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Na (11), Mg (12) және Al (13) элементтері берілген.Әрқайсысының электрондық конфигурациясын жазып, сыртқы қабаттағы электрон саны бойынша оларды оңай иондану (электрон беру) тәртібі бойынша сұрыпта (ең оңайдан ең қиынға). Қысқаша түсіндір.', 2, 14, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрондық конфигурация: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p³.Элементті анықта, қабаттар бойынша бөлінісін жаз, период пен топты көрсет.', 2, 15, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атомтың қабаттар бойынша бөлінісі: (2,8,7). Бұл элементтің кім екенін анықта, атом нөмірін және оған тән электрондық конфигурациясын көрсет.', 2, 16, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 25 элементтің электрондық конфигурациясын жаз.', 2, 17, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атом нөмірі 30 элементтің электрондық конфигурациясын жаз.', 2, 18, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Литий жалыны неге қызыл түсті болып жанады?', 2, 19, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Цезийдің (Cs) сәуле шығаруы көбінесе инфрақызыл аймақта неге байқалады?', 2, 20, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Бір элементтің эксперименттік түрде анықталған электрондық конфигурациясы: \[Ar\] 4s¹ 3d¹⁰.Бұл элементті анықта және неге конфигурация классикалық Aufbau тәртібінен (4s² 3d⁹) ерекшеленгенін түсіндір. Қабаттар бойынша электрондарды көрсет.', 3, 21, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Элемент Cr (хром), атом нөмірі 24. Тәжірибеде конфигурациясы жиі \[Ar\] 4s¹ 3d⁵ болып келеді.Неге Cr конфигурациясы 4s² 3d⁴ емес', 3, 22, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрондық конфигурация: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 4p⁵ (қысқартылған түрде \[Ar\] 4s² 4p⁵ көрсетілген болуы мүмкін).Элементті анықта, қабаттар бойынша бөлініс жазыңдар және оның химиялық табиғатын сипатта (металл/бейметалл).', 3, 23, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Атомтың n=3 қабатындағы электрон саны 12, ал n=4 қабатында 2 электрон бар.Атом нөмірін табыңдар және толық электрондық конфигурациясын көрсетіңдер.', 3, 24, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрондық конфигурация қысқаша: \[Kr\] 5s² 4d¹⁰ 5p².Бұл элементті анықта (атом нөмірі), қабаттар бойынша электрон санын көрсет және қай период пен топқа жататынын анықта.', 3, 25, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Al³⁺ ионының электрондық конфигурациясы 1s² 2s² 2p⁶.Al³⁺-пен изоэлектронды үш түрлі атом/ионды көрсет және олардың қабаттар бойынша бөлінісін жазыңдар.', 3, 26, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрондық конфигурация: \[Xe\] 6s² 4f¹⁴ 5d¹⁰ 6p³.Бұл атомды анықта, әр n деңгейі бойынша электрон санын көрсет және сыртқы қабаттағы (n=6) электрон санын тап. Қай блокқа жатады?', 3, 27, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Натрий мен калийдің жалын түсі әртүрлі екенін байқаймыз. Натрий жалында --- сары, калий жалында --- күлгін түс байқалады. → Бұл айырмашылық неліктен болады?', 3, 28, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Цезийдің (Cs) жалын түсі көк емес, қызыл және инфрақызылға жақын болып келеді. → Неліктен ауыр сілтілік металдардың сәуле шығару толқын ұзындығы ұлғаяды?', 3, 29, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Сілтілік металдарда электрон бір қабатқа секіріп түскенде жарық шығарылады. Егер натрийдің электрон энергиясы 3.37 эВ-тан 2.10 эВ-қа өтсе, қандай толқын ұзындығындағы жарық шығарылады? (1 эВ = 1.6×10⁻¹⁹ Дж, h = 6.63×10⁻³⁴ Дж·с, c = 3×10⁸ м/с)', 3, 30, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), '.Шешуі: Электрон саны = 13 → Al. Период = 3, Топ = III,Валентті электрондар = 3.', 2, 31, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Электрон саны =16 → S (күкірт). Қабаттар: (2,8,6). Период =3. Бейметалл.', 2, 32, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Na: 1s²2s²2p⁶3s¹ → (2,8,1) → валентті 1. Mg: 1s²2s²2p⁶3s² → (2,8,2) → валентті 2. Al: 1s²2s²2p⁶3s²3p¹ → (2,8,3) → валентті 3. Иондану оңайлығы шамамен иондану энергиясына байланысты; жалпы сыртқы қабаттағы электрон неғұрлым аз болса (және толық (стабильді) қабатқа жақын болса) --- соғұрлым жеңіл ионданады. Сондықтан тәртібі: Na \> Mg \> Al (Na ең оңай --- бір электронмен толық 2-ш қабатқа жетеді).', 2, 33, '[]'::jsonb, 'Тәртібі: Na (ең оңай), сосын Mg, сосын Al.'),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Санау: 1s²(2)+2s²2p⁶(8)+3s²3p⁶3d¹⁰(2+6+10=18) + 4s²4p³(2+3=5) → жалпы = 2+8+18+5 = 33 → атом №33 → As (мышьяк). Қабаттар бойынша: (2,8,18,5). Сыртқы n=4 деңгейінде 5 электрон → период = 4. Соңғы конфигурация 4p³ (p-блок) → V-топ (15-топ) --- p-элемент, бейметалға жақын (металлөлшемді элемент ретінде кейбір қасиеттері бар).', 2, 34, '[]'::jsonb, 'As (атом №33); қабаттар: (2,8,18,5); 4-период; 4p³ (p-блок).'),
  ((SELECT id FROM public.topics WHERE week_number = 4), '\[Ar\] = 18 электрон. Қосымша 4s¹ (1) және 3d¹⁰ (10) → жалпы электрон саны = 18 + 1 + 10 = 29. 2) Атом нөмірі 29 → элемент --- Cu (мыс).', 3, 35, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Неліктен 4s¹ 3d¹⁰: d-подқабаттың толық толғанысы (3d¹⁰) ерекше тұрақты конфигурация береді. Бір 4s электронын 3d-қа жылжыту арқылы жалпы электрондық жүйенің энергиясы төмендеп, тұрақтылық артады. Сондықтан тәжірибеде Cu үшін \[Ar\] 4s¹ 3d¹⁰ конфигурациясы байқалады, ал классикалық қарапайым толтыру реті (Aufbau) кейбір өтпелі металдарда толығымен дұрыс болмайды.', 3, 36, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Қабаттар бойынша (n деңгейлеріне сай санау): n=1:2, n=2:8, n=3: 3s²3p⁶3d¹⁰ = 2+6+10 = 18, n=4: 4s¹ = 1 → (2, 8, 18, 1).', 3, 37, '[]'::jsonb, 'Элемент --- Cu (мыс), конфигурация \[Ar\] 4s¹ 3d¹⁰; қабаттар: (2, 8, 18, 1).'),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Қабаттар бойынша (n деңгейлерін қосып санау): n1=2, n2=8, n3=3s²3p⁶3d¹⁰ = 18, n4 = 4s² + 4p⁵ = 7 → (2,8,18,7).', 3, 38, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Химиялық табиғаты: Br --- бейметалл, галогендер тобы. Ол электронды қабылдауға (немесе бірлескен жұптасуға) бейім.', 3, 39, '[]'::jsonb, 'Br (бром), қабаттар: (2,8,18,7), бейметалл (галоген).'),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Барлық қабаттар бойынша: n1 максимум 2, n2 максимум 8 (толық), n3 берілген 12, n4 = 2. Сондықтан жалпы электрон саны = 2 + 8 + 12 + 2 = 24. 2) Атом нөмірі = 24 → Cr (хром).', 3, 40, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Осыдан ыңғайлы толық конфигурация (теориялық Aufbau тәртібі): 1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁴ 4s² → қысқаша \[Ar\] 4s² 3d⁴; бірақ тәжірибеде Cr жиі \[Ar\] 4s¹ 3d⁵ күйінде болады (энергетикалық тұрақтылыққа байланысты).', 3, 41, '[]'::jsonb, 'Атом нөмірі 24 (Cr). Теориялық: \[Ar\] 4s² 3d⁴; тәжірибелік тұрақты күй: \[Ar\] 4s¹ 3d⁵.'),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Қабаттар бойынша: \[Kr\] ішіндегі бөлініс (2,8,18,8) және қосымша: 4d¹⁰ → 4-қабатқа +10 → n4 = 18; 5-қабат: 5s²+5p² = 4 → n5 = 4. Сөйтіп: (2,8,18,18,4).', 3, 42, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Период: n=5 → 5-период. Валентті электрондар: 5s²5p² → 4. Топ: IV (14 топқа эквивалент).', 3, 43, '[]'::jsonb, 'Sn (олово), атом №50; қабаттар: (2,8,18,18,4); 5-период, валентті = 4.'),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Изоэлектронды түрлер: Ne (атом №10), Na⁺ (11 −1 =10), O²⁻ (8 +2 =10). Барлығының қабаттар бойынша бөлінісі: (2,8).', 3, 44, '[]'::jsonb, 'Ne, Na⁺, O²⁻ --- бәрі Al³⁺-пен изоэлектронды; қабаттар: (2,8).'),
  ((SELECT id FROM public.topics WHERE week_number = 4), '\[Xe\] = 54 электрон. Қосымша: 6s² (2) + 4f¹⁴ (14) + 5d¹⁰ (10) + 6p³ (3) = 29. Барлығы = 54 + 29 = 83 → элемент Bi (висмут).', 3, 45, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Қабаттар бойынша жинақтау: \[Xe\] ішіндегі бөлініс (n1..n5) = (2,8,18,18,8) = 54. - 4f¹⁴ → n4 қосымша +14 → n4 = 18 + 14 = 32. - 5d¹⁰ → n5 қосымша +10 → n5 = 8 + 10 = 18. - n6: 6s² + 6p³ = 5. Қорытынды: (n1..n6) = (2, 8, 18, 32, 18, 5). Сыртқы (n=6) электрондар = 5.', 3, 46, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 4), 'Бұл p-блок элементі (6p³) --- Bi; валентті электрондар = 5.', 3, 47, '[]'::jsonb, 'Bi (атом №83); қабаттар: (2,8,18,32,18,5); n=6 сыртқы = 5; p-блок.');

