  ((SELECT id FROM public.topics WHERE week_number = 5), 'Бор моделі бойынша сутегі атомындағы электрон n=3 деңгейінен n=2 деңгейіне өткенде шығатын фотонның толқын ұзындығын анықтаңыз. Қысқаша формула көрсетіңіз және нәтижені беріңіз.', 1, 7, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 5), 'Сыртқы электрондарға ішкі электрондардың әсері қандай? Яғни «экрандау» немесе «эффективті ядролық заряд» ұғымын түсіндіріңіз және формула түрінде жазыңыз.', 1, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 5), 'Натрийдың (Na) жалғыз валентті электронынан иондағандағы және хлордың (Cl) бір электрон алғандағы реакциясы: Na → Na⁺ + e⁻ және Cl + e⁻ → Cl⁻.Осы екі реакцияның нәтижесінде қандай тұз түзіледі және ол қандай бөлшектерден тұрады?', 1, 9, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 5), 'Күрделі спектрлерді сипаттағанда қолданылатын негізгі кванттық сандардың (n, l, m, s) әрқайсысының қысқаша мағынасын 1 сөйлемнен аса алмайтын етіп жазыңыз. ## Жауаптары: ## 1-есеп', 1, 10, '["Z = 8, A ≈ 16","p = Z = 8","e = Z = 8","n = A - Z = 16 - 8 = 8","## 2-есеп","Z = 11","1s² 2s² 2p⁶ 3s¹","Қабықтар бойынша: K(2), L(8), M(1)","## 3-есеп","Ca (Z = 20), топ = II, период = 4","eвал = 2, ион: Ca²⁺","## 4-есеп","Cl (Z = 17)","K(2)L(8)M(7) → eвал = 7","Cl + e⁻ → Cl⁻","## 5-есеп","Сұрақ:","Периодтық жүйедегі элемент қасиеттерінің өзгеру заңдылығы","Солдан оңға: rатом ↓, Eион ↑, χ ↑","Жоғарыдан төмен: rатом ↑, Eион ↓","## 6-есеп","Электрондық конфигурация: 1s² 2s² 2p⁶ 3s² 3p⁴","Сыртқы қабатта 6 электрон → 3-период, VI-топ → S","Z = 16","## 7-есеп","n₁ = 2, n₂ = 3, R = 1.097×10⁷ м⁻¹","1/λ = R(1/n₁² − 1/n₂²)","1/λ = 1.097×10⁷(1/4 − 1/9)","λ = 6.56×10⁻⁷ м = 656 нм","## 8-есеп","Сұрақ:","Экрандау (shielding) әсері дегеніміз не?","Ішкі электрондар сыртқы электронды ядро әсерінен жасырады.","Zэфф = Z − σ","(Z --- ядро заряды, σ --- экрандау тұрақтысы)","Экрандау артқан сайын r атом↑, E ион↓","## 9-есеп","Na → Na⁺ + e⁻","Cl + e⁻ → Cl⁻","Na⁺ + Cl⁻ → NaCl","Түзілген зат --- NaCl (иондық байланыс)","## 10-есеп","Сұрақ:","Кванттық сандар және олардың мағынасы","n = 1,2,3,... --- энергетикалық деңгей","l = 0,1,2,3 --- орбиталь пішіні (s,p,d,f)","m = −l...0...+l --- орбиталь бағыты","s = ±½ --- спин бағыты","## 2-Деңгей"]', 'λ = 656 нм (Hα сызығы)'),
