INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Электронның спин кванттық саны s = 1\\2. Спин проекциясының мүмкін мәндерін анықтаңыз.', 1, 0, '["Спин проекциясы:![](media/image1.png){width=\"0.6500568678915135in\" height=\"0.5000437445319335in\"}","![](media/image2.png){width=\"1.6456692913385826in\" height=\"0.6392268153980752in\"}","Электрон спинінің екі ғана мүмкін мәні бар:","![](media/image3.png){width=\"1.2677165354330708in\" height=\"0.49711286089238843in\"}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Егер электрон үшін орбиталық кванттық сан ( l = 1 ) болса, толық импульс моментінің ( J ) мүмкін мәндерін табыңыз.', 1, 1, '["Электрон үшін:","![](media/image4.png){width=\"0.6534722222222222in\" height=\"0.5in\"}","J = L + S және J = L -- S","![](media/image5.png){width=\"1.312150043744532in\" height=\"1.0265638670166228in\"}","![](media/image6.png){width=\"0.781486220472441in\" height=\"0.40688976377952757in\"}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Егер атом күйінде толық спин ( S = 1 ) болса, мультиплеттілікті анықтаңыз.', 1, 2, '["Мультиплет формуласы:","2S + 1","2 ∗1 + 1 = 3","Мультиплеттілік = 3 → триплет"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Сутегі атомының энергиясы формула бойынша: ![](media/image7.png){width="1.0667596237970254in" height="0.5000437445319335in"} n = 2 үшін энергияны табыңыз.', 1, 3, '["![](media/image8.png){width=\"1.3084470691163606in\" height=\"1.450125765529309in\"}","![](media/image9.png){width=\"1.3084470691163606in\" height=\"0.5000437445319335in\"}"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Егер l = 2 , s = 1\\2 болса, энергия деңгейі неше ішкі деңгейге бөлінеді?', 1, 4, '["Мүмкін J мәндері:","![](media/image10.png){width=\"1.2440944881889764in\" height=\"0.8744192913385826in\"}","Яғни екі түрлі J бар → екі энергия деңгейі.","Энергия деңгейі 2 ішкі деңгейге бөлінеді."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Сутегі атомы үшін n = 3 . Энергиясын және n = 2 деңгейіне өткендегі фотон энергиясын табыңыз.', 2, 5, '["![](media/image14.png){width=\"2.175188101487314in\" height=\"1.4417913385826773in\"}","Фотон энергиясы:","![](media/image15.png){width=\"1.9418350831146107in\" height=\"1.1917694663167104in\"}","Фотон энергиясы ≈ 1.89 эВ"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Егер атом күйінде S = 3\\2 болса, мультиплеттілікті анықтаңыз.', 2, 6, '["![](media/image16.png){width=\"1.7168153980752405in\" height=\"0.8667421259842519in\"}","Мультиплеттілік = 4 (квартет)"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 6), '(Спин-орбиталық бөліну энергиясы) Спин-орбиталық әсерлесу энергиясы жуық түрде: ![](media/image21.png){width="1.3334492563429572in" height="0.5000437445319335in"} мұндағы: ![](media/image22.png){width="5.456692913385827in" height="1.0684437882764655in"} Энергия айырмасын табыңыз.', 3, 7, '["![](media/image23.png){width=\"5.117109580052493in\" height=\"2.0751793525809274in\"}","![](media/image24.png){width=\"4.489488188976378in\" height=\"2.354330708661417in\"}","![](media/image25.png){width=\"4.299212598425197in\" height=\"2.174560367454068in\"}","![](media/image26.png){width=\"1.2614238845144357in\" height=\"0.4215277777777778in\"}"]', 'Энергия айырмасы:'),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Алдыңғы есептегі энергия айырмасына сәйкес фотон толқын ұзындығын табыңыз.', 3, 8, '["![](media/image27.png){width=\"1.7584853455818024in\" height=\"0.5250459317585302in\"}","![](media/image28.png){width=\"0.8334055118110236in\" height=\"0.6167202537182852in\"}","hc=1240 эВ$\\times$нм","![](media/image29.png){width=\"1.675145450568679in\" height=\"1.3001126421697289in\"}"]', 'λ≈4.1 мм'),
  ((SELECT id FROM public.topics WHERE week_number = 6), 'Сутегі атомында n=4→n=2 өтудегі фотон энергиясын табыңыз.', 3, 9, '["![](media/image32.png){width=\"1.9162062554680666in\" height=\"1.5127952755905512in\"}"]', 'E=2.55 эВ');

