INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Квантық механика элементтері және атомның магниттік қасиеттері бойынша есептер', 1, 0, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Электрон 1.2×10⁶ м/с жылдамдықпен қозғалады. Оның де Бройль толқын ұзындығын табыңыз.', 1, 1, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Фотонның жиілігі 6.0×10^14 ^Гц. Осы фотонның энергиясын джоульмен есептеңіз. 3. Электрон фермион ба, әлде бозон ба?', 1, 2, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Гидроген атомының негізгі (n=1) энергиясы қандай (эВ-те)? (Ескерту: E~n~=−13.6 eВ/n^2^)', 1, 3, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Электронның спині s=1/2. Оның проекциясы m~s~=+1/2 болғанда спиннің магниттік моментінің бағыты қалай байланысты болады?', 1, 4, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Нейтрал атом (бір валентті электрон) градиенттелген магнит өрісіне түскенде, спин бағыты бойынша екіге бөлінеді. Егер магнит өрісінің градиенті $\frac{\partial Bz}{\partial z}$=10^3^ T/м және атомның магниттік моменті шамамен μ~B~ онда бөлшектің z бағыты бойынша күшінің шамасы қандай?', 2, 5, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Бір электронды ион He^+^ үшін (ядро заряды Z=2), негізгі күйдегі (n=1) энергияны және бозон радиусын салыстырмалы түрде анықтаңыз: E~n~ және a~n~ H атомымен салыстырғанда қалай өзгереді? (нұсқа: E~n~∝Z^2^ a~n~∝1/Z)', 2, 6, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Қоршаған ортада жылдамдығы v=2.0×10^5^ м/с электрон үшін де Бройль толқын ұзындығы қандай? Салыстырып, егер оның импульсі екі есе артса, толқын ұзындығы қалай өзгереді?', 2, 7, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Электрондағы орбитальдық магниттік моменттің m~l~=1 кезінде сыртқы магнит өрісі B=1.5 T болғанда орбитальдық магниттік энергияның өзгерісі қанша? (мұндағы: орбитальдық магниттік момент шамамен μ~L~=m~l~μ~B~.)', 2, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Квант бөлшектің классикалық тұрғыдан өтуі мүмкін емес потенциал тосқауылын кванттық түрде өту ықтималдығына байланысты қысқаша анықтама беріңіз: тосқауыл биіктігі жоғарылаған сайын өтудің ықтималдығы қалай өзгереді және неліктен?', 2, 9, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Бірөлшемді шектеулі қораптың ұзындығы L=1.0 нм. Электронның ең төменгі үш энергия деңгейін және оларды эВ-ке аудару үшін формуланы табыңыз.', 3, 10, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Кванттық гармоникалық осциллятордың (ω жиілікті) энергиясы E~n~=ℏω(n+1/2). Егер ℏω=0.05 eB, n=0,1,2 үшін энергияларды табыңыз және n=1 ден n=0 ге өтудің энеhuия айырмашылығын жазыңыз.', 3, 11, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Бөлшек магниттік моментінің μ=μ~B~ және жылдамдығы v=500 м/с. Градиенттен өткен ұзындығы l=0.1 м және өріс градиенті $\frac{\partial B}{\partial z}$=2×10^3^ T/м. Шегі бойынша з-бағыт бойынша орын ауыстыру амплитудасын жуық мәнмен есептеңіз', 3, 12, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Гидроген атомының негізгі күйінде (n=1) электронның радиус бойынша ықтималдық тығыздығының максимумында орналасқан радиусты табыңыз', 3, 13, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Гидроген сияқты жеңіл атомдарда спин-орбита әсері кішкентай коррекция береді. Сипаттаңыз: спин-орбита өзара әрекеттену энергиясы қандай факторларға тәуелді және n, l, j кванттық сандарымен қалай байланысты?', 3, 14, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), '1) $\lambda = \frac{h}{m_{e}\vartheta} = \frac{6.626 \times 10^{- 34}}{9.109 \times 10^{- 31} \times \ 1.2 \times 10^{6}} = 6.06*10^{- 10}м$ 2) E=h$\nu = 6.626 \times 10^{- 34}*6*10^{14} = 3.98*10^{- 19}Дж = 2.48\ eB$', 1, 15, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Электрон --- фермион, себебі оның спині s = 1/2. Фермиондар Ферми--Дирак статистикасына бағынады және Паули принципіне сәйкес бір кванттық күйге бірдей спин проекцияларымен ғана шектелген орындар болады. 4) E~n~=−13.6 eВ/n^2^ n=1 $E_{1} = - 13.6\ eB = \ - 13.6*1.602*10^{- 19} = \ - 2.17872*10^{- 18}$Дж', 1, 16, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 7), 'Спин проекциясы m~S~ = +1/2 болса, спин проекциясы оң бағытта және сәйкес спиндік магниттік моменттің проекциясы да сол бағытта болады.', 1, 17, '[]'::jsonb, NULL),
