INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Молекуладағы қозғалыс түрлері. Молекула энергиясы. Молекулалық спектрлер [Бұл құжатта үш бөлімнен тұратын есептер жинағы берілген:\]{.underline}', 1, 0, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Қозғалыс түрлері мен кинетикалық энергия бойынша -- оңай деңгей (5 есеп)', 1, 1, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Әр есептің толық шешу жолы көрсетілген. [Қолданылатын тұрақтылар:]{.underline} Больцман тұрақтысы: k = 1.38×10⁻²³ Дж/К Газ тұрақтысы: R = 8.314 Дж/(моль·К) Авогадро саны: N_A = 6.022×10²³ молекула/моль', 3, 2, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '1: Біре молекуланың T = 300 K температурадағы орташа кинетикалық энергясын табыңыз (молекуланың бір ғана трансляциялық удовольствие бар деп есептеңіз).', 1, 3, '["Орташа кинетикалық энергия: ⟨E⟩ = (3/2) k T = (3/2)·1.38e-23·300 = 6.210e-21 Дж.","6.210e-21 Дж ≈ 6.210e-21 Дж."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '2: Молекулалар газында температура 273 K-дан 546 K-қа дейін көтерілді. Орташа кинетикалық энергия қалай өзгереді?', 1, 4, '["Орташа кинетикалық энергия ∝ T. T екі есеге артқандықтан (273→546), орташа кинетикалық энергия да екі есеге артады."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '3: Молекулаға тән жылдамдықтың (rms) анықтамасы: v_rms = √(3kT/m). Егер молекуланың массасы m = 4.65×10⁻²⁶ кг (азот молекуласы N₂ үшін шамамен), T = 300 K болса, v_rms табыңыз.', 1, 5, '["v_rms = √(3kT/m) = √(3·1.38e-23·300 / 4.65e-26) = 516.81 м/с."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '4: Молекуланың трансляциялық энергиясының (орташа) формуласы қандай? Және 1 мол газдың орташа кинетикалық энергиясын R мен T арқылы өрнектеңіз.', 1, 6, '["Орташа трансляциялық энергия бір молекула үшін ⟨E⟩ = (3/2) k T. 1 мол (N_A молекула) үшін U = N_A·⟨E⟩ = N_A·(3/2) k T = (3/2) R T."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '5: Температура 0 °C (273 K) болғанда бір мол идеал газының ішкі энергиясы (тек трансляциялық қозғалыс қабылдансын) қандай болады?', 1, 7, '["U = (3/2) R T = (3/2)·8.314·273 = 3404.58 Дж/моль."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '6. Орташа деңгейі --- Есеп 6: Сутегі молекуласының (H₂) бір молекуласының орташа кинетикалық энергиясын T = 500 K кезінде есептеңіз. H₂ массасы ≈ 3.32×10⁻²⁷ кг. Қосымша: осы молекула үшін v_rms табыңыз.', 2, 8, '["⟨E⟩ = (3/2) k T = (3/2)·1.38e-23·500 = 1.035e-20 Дж.","v_rms = √(3kT/m) = √(3·1.38e-23·500 / 3.32e-27) = 2496.99 м/с.","7.  Орташа деңгейі --- Есеп 7:","1,00 моль аргон (арнайы атомарлық) газының ішкі энергиясын T = 400 K кезінде табыңыз (аргон тек трансляциялық қозғалысқа ие --- 3/2 RT).","U = (3/2) R T = (3/2)·8.314·400 = 4988.40 Дж/моль.","8.  Орташа деңгейі --- Есеп 8:","Молекуланың внутрішньо ротациялық деңгейіне қатысты: Кіші молекулаға (диатомдық) ротациялық орташа энергия = kT. 1 молекула үшін және 1 мол үшін өрнектеп көрсетіңіз.","Ротациялық орташа энергия (классикалық) бір молекула үшін ⟨E_rot⟩ = k T. 1 мол үшін U_rot = N_A k T = R T.","9.  Орташа деңгейі --- Есеп 9:","Екіатомдық газда (бағыттар: трансляция + ротация) бір молекула үшін орташа кинетикалық энергия қандай? (Үздіксіз классикалық статистикада)","Екіатомдық газ классикалық жағдайда (тек трансляция+ротация) қосынды энергия: ⟨E⟩ = (3/2)kT (трансляция) + (1)kT (ротация) = (5/2) k T бір молекула үшін.","1 мол үшін U = (5/2) R T.","10. Орташа деңгейі --- Есеп 10:","Температураны T1=300 K-ден T2=600 K-ға өзгертсек, молекуланың ротациялық энергиясы қалай өзгереді, егер ротациялық энергия ∝ T болса?","Ротациялық энергия ∝ T болғандықтан, T екі еселенсе, ротациялық энергия да екі еселенеді."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '11. Күрделі деңгейі --- Есеп 11: Ковалентті байланыс күші бар диатомдық молекуланың негізгі тербеліс жиілігі ν = 6.0×10¹³ Гц деп берілсін. Осы тербеліс үшін кванттық тербелмелі энергия деңгейлері E_n = hν (n + 1/2) формуласы бойынша n=0 және n=1 деңгейлерінің энергияларын есептеңіз (h = 6.626×10⁻³⁴ Дж·с).', 3, 9, '["E_0 = hν(1/2) = 6.626e-34·6.000e+13·0.5 = 1.988e-20 Дж.","E_1 = hν(3/2) = 6.626e-34·6.000e+13·1.5 = 5.963e-20 Дж.","ΔE = E_1 − E_0 = 3.976e-20 Дж = 3.976e-20 Дж = hν.","12. Күрделі деңгейі --- Есеп 12:","Молекулалық спектр: Егер молекуланың бір спектр сызығының энергиясы ΔE = 2.0×10⁻²⁰ Дж болса, оның жиілігін ν табыңыз және толқын ұзындығын λ есептеңіз (c = 3.00×10⁸ м/с).","ν = ΔE / h = 2.000e-20 / 6.626e-34 = 3.018e+13 Гц.","λ = c / ν = 3.000e+08 / 3.018e+13 = 9.939e-06 м.","13. Күрделі деңгейі --- Есеп 13:","Диатомдық молекуланың ротациялық энергия деңгейлері (қатты жерлерде) E_J = (h² / 8π² I) J(J+1). Берілген момент инерциясы I = 1.0×10⁻⁴⁶ кг·м² үшін J=0→1 өтпелігі үшін энергияны есептеңіз.","E(J=0→1) = h²/(4π² I) = (6.626e-34)² / (4·π²·1.000e-46) = 1.112e-22 Дж.","14. Күрделі деңгейі --- Есеп 14:","Бір молекуланың тербелмелі энергиясының алғашқы екі деңгейі арасындағы энергия айырмасы ΔE = hν. Егер ν = 5.0×10¹³ Гц болса, осы ΔE-ді Дж және эВ-те есептеңіз (1 эВ = 1.602×10⁻¹⁹ Дж).","ΔE = hν = 6.626e-34·5.000e+13 = 3.313e-20 Дж = 0.207 эВ.","15. Күрделі деңгейі --- Есеп 15:","Термодинамика: 1,00 моль екіатомдық идеал газды T = 1000 K-ге дейін қыздырғанда (постоянный көлемде) оның ішкі энергия қалай өзгереді? (Үш инвариант: Cv = (5/2) R). ΔU = n Cv ΔT табыңыз.","Cv = (5/2)R = 20.785 Дж/(моль·К).","ΔT = 1000 − 300 = 700 K.","ΔU = n Cv ΔT = 1·20.785·700 = 14549.50 Дж.","Құжат жасалған: 2025-12-10 15:52:14"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '> Тақырыбы: Земан эффект.Пашен Бак эффект. Паули принципі .Паули притнципі.Рентгендік спектрлар.', 1, 10, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Земан эффект.Пашен Бак эффект. Паули принципі .Паули притнципі.Рентгендік спектрлар', 1, 11, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Зееман эффекті -- атом спектрлерінің сыртқы магнит өрісінің әсерінен ыдырауы немесе бірнеше компонентке бөлінуі. Бұл құбылыс электрон орбитальдарының магниттік моментке ие болуымен түсіндіріледі. Магнит өрісі электрондардың энергетикалық деңгейлерін ажыратады, нәтижесінде сызықтар жұқа бірнеше сызыққа бөлінеді. Зееман эффекті атом құрылысы мен спектроскопияда маңызды рөл атқарады.', 1, 12, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Пашен--Бак эффекті --- күшті магнит өрісі жағдайында байқалатын Зееман эффектінің шектік түрі. Өріс өте үлкен болғанда орбитальдық және спиндік моменттердің байланысы үзіледі, сондықтан спектрдің ыдырау сипаты өзгереді. Яғни Л--S байланысуы әлсіреп, әрбір момент өріспен жеке әрекеттеседі. Бұл эффект жоғары өрісті магниттерде және астрофизикада қолданылатын аса дәл спектрлік өлшеулерде маңызды.', 1, 13, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Паули принципі (тыйым салу принципі) -- бір атомдағы екі электронның кванттық сандарының толық тобы бірдей бола алмайтынын айтады. Яғни бір орбитальда максимум екі электрон орналасады және олардың спиндері қарама-қарсы болуы тиіс. Бұл принцип атомдағы электрондық қабықша құрылымын, периодтық жүйенің заңдылығын және химиялық қасиеттердің периодтылығын түсіндіретін негізгі ереже.', 1, 14, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Рентгендік спектрлар -- жоғары энергиялы фотондардың затпен әрекеттесу нәтижесінде пайда болатын сәулелер. Олар сипаттамалық және тежелу спектрларына бөлінеді. Сипаттамалық рентген сәулелері атом ішкі қабатындағы электрондардың ауысуынан пайда болады және әр элемент үшін бірегей. Ал тежелу спектрі электрондардың баяулауынан туындайды. Рентген спектрлері материалдардың құрылымын зерттеуде, медицинада және қатты дене физикасында кең қолданылады. 1\. Жеңіл деңгей (5 есеп) ### 1-есеп (жеңіл).', 1, 15, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Магнит өрісінде спектр сызығы 3 компонентке ыдырады. Бұл қандай Зееман эффекті? Қарапайым Зееман эффектінде әрбір сызық үшке: (m = --1, 0, +1) бөлінеді.', 1, 16, '["### 2-есеп (жеңіл)."]', 'Қарапайым Зееман эффекті.'),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'Паули принципіне сай, бір орбитальда қанша электрон орналасады?', 1, 17, '["Спиндері қарама-қарсы екі электрон.","### 3-есеп (жеңіл)."]', '2 электрон.'),
  ((SELECT id FROM public.topics WHERE week_number = 8), '220 нм толқын ұзындығындағы жарық рентген сәулесі ме?', 1, 18, '["Рентген диапазоны: 0,01--10 нм.","220 нм → ультракүлгін.","### 4-есеп (жеңіл).","Зееман эффекті қандай өрісте байқалады?","### 5-есеп (жеңіл)."]', 'Магнит өрісінде.'),
  ((SELECT id FROM public.topics WHERE week_number = 8), '### Пашен--Бак эффекті қандай шартта көрінеді? Жауабы: Өте күшті магнит өрісінде (LS-байланыс үзіледі). ###', 1, 19, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '![](media/image1.png){width="4.633497375328084in" height="2.6547101924759406in"} ![](media/image2.png){width="4.540029527559055in" height="2.169504593175853in"} ![](media/image3.png){width="4.511128608923885in" height="2.854084645669291in"} ![](media/image4.png){width="4.500566491688539in" height="2.390330271216098in"} ### 10-есеп (орташа).', 2, 20, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), '### Зееман эффекті кезінде спектр сызығы 7 компонентке бөлінді. Қандай эффект? 7 компонент → күрделі Зееман эффекті (спин әсер етеді).', 2, 21, '[]'::jsonb, 'Күрделі Зееман эффекті.'),
  ((SELECT id FROM public.topics WHERE week_number = 8), '![](media/image5.png){width="4.227272528433946in" height="2.5819958442694664in"} ### 12-есеп ( күрделі.). Пашен--Бак эффекті кезінде LS-байланыс жоғалады. l = 1, s = 1/2. Магнит квант сандарының мүмкін мәндерін жазу.', 3, 22, '["Моменттер өріспен бөлек әсерлеседі:","m_l = --1, 0, +1","m_s = --1/2, +1/2","Комбинация саны = 3 × 2 = 6.","![](media/image6.png){width=\"4.612917760279965in\" height=\"2.72709208223972in\"}","![](media/image7.png){width=\"4.587374234470691in\" height=\"2.2109383202099737in\"}","### 15-есеп (күрделі).","Паули принципін бұзатын электрон конфигурациясын анықтаңыз:","a) 1s² 2s² 2p³","b) 1s² 2s² 2p⁶","c) 1s² 2s³ 2p²","2s орбитальда максимум 2 электрон.","Ал c-де 3 электрон орналасқан → принцип бұзылады.","Зертханалық жұмыс.","Зееман эффектісінің классикалық моделі.","Зееман эффектісінің кейбір принциптерін классикалық модельді қолдана отырып көрсетуге болады, ол атом ядросының айналасында қозғалатын электронның механикалық және магниттік моменттері ![](media/image8.png){width=\"1.156411854768154in\" height=\"0.3229615048118985in\"}","қатынасымен байланысты екеніне негізделген. Осылайша, классикалық модель, кванттық модельден айырмашылығы, электронның ішкі механикалық импульсін (спинін) және магниттік моментін ескермейді және сондықтан тек атомдағы электрон спиндері өтелетін арнайы жағдайда ғана дұрыс нәтижелер бере алады (s = 0). Таза тарихи себептерге байланысты бұл жағдай қалыпты (қарапайым) Зееман эффектісі деп аталады, ал s ≤ 0 үшін Зееман эффектісі аномальды (күрделі) деп аталады.","Классикалық физика заңдарынан оңай көрініп тұрғандай, сыртқы магнит өрісіндегі орбиталық электрон тогы (яғни, магниттік төбе) H\\~ бағыты бойынша Лармор жиілігімен прецессияға ұшырайды: ![](media/image9.png){width=\"1.8335892388451445in\" height=\"0.3153860454943132in\"}","Қалыпты Зееман компоненттерінің спектрлік құрамы мен поляризациясын түсіндіру үшін электронның күрделі қозғалысын қарапайым компоненттерге жіктеу қажет.","![](media/image10.png){width=\"2.239896106736658in\" height=\"3.0004188538932635in\"}","1-сурет: Зееман эффектінің классикалық моделі"]', 'c) 1s² 2s³ 2p²'),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'суретте көрсетілгендей зертханалық анықтамалық жүйені (x, y, z) енгізейік -- H\~ магнит өрісі z осі бойымен бағытталған, ал (x, y) жазықтығы оған перпендикуляр. Магнит өрісі бастапқыда жоқ деп есептейік, яғни Ω = 0 -- прецессиялық қозғалыс жоқ. Орбиталық қозғалысты (x, y) жазықтығындағы және z осі бойымен қозғалысқа жіктейміз. Дөңгелек орбиталық қозғалыстың (x, y) жазықтығына проекциясы эллипс бойымен қозғалыс болып табылады, оны өз кезегінде 2-суретте көрсетілгендей екі дөңгелек айналудың қосындысы ретінде көрсетуге болады. ![](media/image11.png){width="3.1983628608923884in" height="2.062787620297463in"}', 3, 23, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 8), 'сурет: Дөңгелек орбиталық қозғалыстың проекциясын дөңгелек айналулардың қосындысы ретінде көрсету Мұнда R\~1 және R\~2 векторлары эллипстің үлкен осіне қатысты симметриялы түрде орбиталық қозғалыстың бұрыштық жылдамдығы ω0 болатын қарама-қарсы бағытта айналады. R\~ векторының ұшы үлкен жарты осі ![](media/image12.png){width="0.9063768591426071in" height="0.34379811898512685in"} тең болатын эллипс бойымен қозғалады, ал кіші жарты осі ![](media/image13.png){width="1.0209755030621173in" height="0.3854702537182852in"} (эллипс теңдеуі параметрлік түрде оңай алынады). Өз кезегінде, электронның дөңгелек орбиталық қозғалысын екі сызықтық ортогоналды гармоникалық тербелістердің қосындысына жіктеу арқылы бұл қозғалыстың z осіне проекциясы ω0 жиілігі бар гармоникалық тербеліс екенін оңай көруге болады. Жоғарыда айтылғандай, магнит өрісі қолданылған кезде, нәтижесінде пайда болған электрон қозғалысы орбитаның жылдам орбиталық айналуы мен прецессиясының қосындысына тең болады; яғни орбиталық қозғалыс z осінің айналасындағы бұрыштық жылдамдықпен Ω айналумен қабаттасады. z осі бойындағы тербелістер өзгеріссіз қалады, R\~ 1 векторының айналу жылдамдығы төмендейді, ал R\~ 2 векторының айналу жылдамдығы Ω-ға артады. Сәулеленуші атомның элементар диполь моделін қолдана отырып, сыртқы магнит өрісінің бағыты бойынша сәулелену спектрінде ω1,2 = ω0 ± Ω жиіліктері бар екі дөңгелек поляризацияланған толқын ғана болатынын (қалыпты Зееман дублеті), ал перпендикуляр бағытта ω1, ω0, ω2 жиіліктерінде үш сызықтық поляризацияланған компонент байқалатынын (қалыпты Зееман триплеті) оңай көруге болады. Сызықтың бөлінуі әдетте өте аз болғандықтан, яғни \|ω1 − ω2\| \<\< ω0, статистикалық пайымдаулардан электрон қозғалысының үш компонентінің әрқайсысының орташа кинетикалық энергиясы (еркіндік дәрежелері) шамамен бірдей екендігі шығады. Бұл магнит өрісі болмаған кезде сәулелену сызығының қарқындылығы I0 деп белгіленсе, онда Зееман компоненттерінің қарқындылығы дублетте I0/2 және I0/2, ал триплетте I0/4, ', 3, 24, '[]'::jsonb, NULL);

