INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 9), '![](media/image1.png){width="6.496527777777778in" height="3.7006944444444443in"}![](media/image2.png){width="6.496527777777778in" height="7.136805555555555in"}![](media/image3.png){width="6.496527777777778in" height="4.386805555555555in"}![](media/image4.png){width="6.496527777777778in" height="4.884722222222222in"}![](media/image5.png){width="6.496527777777778in" height="3.6847222222222222in"}![](media/image6.png){width="6.496527777777778in" height="2.463888888888889in"}![](media/image7.png){width="6.496527777777778in" height="3.964583333333333in"}![](media/image8.png){width="6.496527777777778in" height="5.345833333333333in"}![](media/image9.png){width="6.496527777777778in" height="2.1493055555555554in"}![](media/image10.png){width="6.496527777777778in" height="4.709027777777778in"}![](media/image11.png){width="6.21961832895888in" height="3.3129625984251967in"}![](media/image12.png){width="6.496527777777778in" height="2.575in"}![](media/image13.png){width="6.496527777777778in" height="2.879166666666667in"}![](media/image14.png){width="6.496527777777778in" height="5.048611111111111in"}', 1, 0, '[]'::jsonb, NULL);

INSERT INTO public.labs (topic_id, title_kz, title_ru, theory_kz) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 9), 'Атомның магниттік моменті. Магниттік резонанс. Электронды парамагниттік резонанс — зертханалық жұмыс', 'Магнитный момент атома. Магнитный резонанс. ЭПР — лабораторная работа', 'Тақырып: Атомдық құрылым, ядролық ыдырау және элементар бөлшектердің қасиеттері

**1. Кіріспе**

Атом, ядролық физика және элементар бөлшектер физикасы — бұл физиканың негізгі салаларының бірі, олар атомдық құрылым, ядролық реакциялар, бөлшектердің қасиеттері мен өзара әсерлесулерін зерттейді. Осы зертханалық жұмыс атомдық ядролардың қасиеттерін, ядролық ыдырау процестерін және элементар бөлшектердің өзара әрекеттесуін зерттеуге бағытталған.

**2. Зерттеу мақсаты**

Атомның құрылымы мен ядролық ыдыраудың негіздері туралы білім алу.

Ядролық реакциялар мен элементар бөлшектердің энергиясын зерттеу.

Элементар бөлшектердің массасын, зарядын және жылдамдығын анықтау.

**3. Зертханалық жұмысқа арналған құралдар мен жабдықтар**

Гейгер-Мюллер есептегіші (GM есептегіші) — радиоактивті ыдырауларды анықтау үшін.

Рентгенді аппарат — атом ядросының энергиясын зерттеу үшін.

Таблицалар мен кестелер — атомның массасын, радиусы мен энергиясын есептеу үшін.

Спектрометр — элементар бөлшектердің энергиясын зерттеу үшін.

Компьютерлік бағдарлама (мысалы, MATLAB, Python) — мәліметтерді өңдеу және графиктерді салу үшін.

**4. Теориялық бөлім**

**4.1. Атомның құрылымы**

Атом ядросы протондар мен нейтрондардан тұрады, ал айналасында электроны орбиталар бойымен қозғалады. Ядроның ішіндегі нуклондар бір-бірімен ядролық күш арқылы байланысады. Электрондар орбиталарына кванттық механика заңдары әсер етеді. Ядроның энергиясы оның байланыс энергиясына байланысты, ал байланыс энергиясы массаның жетіспеушілігімен анықталады.

**4.2. Ядролық ыдырау**

Ядролық ыдырау — бұл атом ядросының ішкі құрылымының өзгеру процесі. Радиоактивті ыдырау кезінде ядро бір немесе бірнеше бөлшектерге ыдырайды, бұл процесс энергияның бөлінуіне алып келеді. Ыдыраудың екі түрі бар: альфа ыдырау және бета ыдырау.

**4.3. Элементар бөлшектер**

Элементар бөлшектер — бұл материялық заттың ең кіші бөлшектері, олар қайта бөлінбейді және ішкі құрылымы жоқ. Бұларға электрондар, протондар, нейтрондар, нейтрино және басқа да бөлшектер жатады. Элементар бөлшектердің энергиясын зерттеу үшін арнайы жылдамдатқыштар мен детекторлар қолданылады.

**5. Зертханалық жұмыс кезеңдері**

**5.1. Атом құрылымын зерттеу**

Мақсат: Атомның құрылымын зерттеу үшін рентген сәулелерінің әсерін бақылау.

Жабдық: Рентген аппараты, экраны бар детектор.

Процедура:

Рентген сәулесін қолдана отырып, атомның ішкі құрылымын зерттеу.

Рентген сәулелерінің атомның ішіндегі электронына әсерін байқап, фотонның шығарылуын тіркеу.

Сәулеленудің толқын ұзындығын және энергиясын анықтау.

Нәтиже: Бұл эксперимент арқылы атомның электронды құрылымын, оның энергия деңгейлерін және электрондардың қозғалысын түсінуге болады.

**5.2. Ядролық ыдырауды зерттеу**

Мақсат: Радиоактивті ыдырауды және оның жартылай ыдырау уақытын зерттеу.

Жабдық: Гейгер-Мюллер есептегіші.

Процедура:

Радиоактивті көз (мысалы, 60Co^{60}Co60Co) қолдану арқылы ядролық ыдырау процесін бақылау.

Ыдырау санын уақыт бойынша тіркеп, жартылай ыдырау уақытын есептеу.

Нәтиже: Бұл эксперимент радиоактивті ыдыраудың заңдылықтарын зерттеуге мүмкіндік береді, сондай-ақ жартылай ыдырау уақытын анықтауға болады.

**5.3. Элементар бөлшектердің энергиясын зерттеу**

Мақсат: Элементар бөлшектердің энергиясын анықтау.

Жабдық: Спектрометр.

Процедура:

Элементар бөлшектердің жылдамдығын өлшеу үшін жоғары энергиялы бөлшектерді пайдалану.

Спектрометр көмегімен бөлшектердің энергиясын анықтау.

Нәтиже: Бұл эксперимент элементар бөлшектердің жылдамдығын, массасын және зарядын анықтауға көмектеседі.

**6. Мәліметтерді өңдеу**

Ядролық ыдыраудың жартылай ыдырау уақытын есептеу үшін алынған мәліметтерді экспоненциалды заң бойынша өңдеу.

Атомның құрылымы туралы мәліметтерді рентген спектрограммасы арқылы талдау.

Элементар бөлшектердің энергиясын спектрді талдау арқылы анықтау.

**7. Қорытынды**

Зертханалық жұмыстың нәтижесінде атомдық құрылым мен ядролық реакциялар туралы негізгі түсініктер алынды. Ядролық ыдырау процестері мен элементар бөлшектердің энергиясын зерттеу барысында алынған мәліметтер арқылы осы салалардың теориясы мен практикасы тереңірек түсінілді. Бұл зерттеулер атом және ядролық физика саласында болашақ зерттеулерге негіз бола алады.

**8. Пайдаланылған әдебиеттер**

1. Хиггс, П. "Элементар бөлшектер және олардың өзара әрекеттесулері", "Наука", 2010.
2. Алтынбеков, Т., Исламбеков, А. "Ядролық физика негіздері", "Ғылым", 2015.
3. Тойбаков, Ж. "Атомдық физика", "Мектеп", 2018.')
