INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 12), 'Молекуладағы қозғалыс түрлері. Молекула энергиясы. Молекулалық спектрлер [Бұл құжатта үш бөлімнен тұратын есептер жинағы берілген:\]{.underline}', 1, 0, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), 'Қозғалыс түрлері мен кинетикалық энергия бойынша -- оңай деңгей (5 есеп)', 1, 1, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), 'Әр есептің толық шешу жолы көрсетілген. [Қолданылатын тұрақтылар:]{.underline} Больцман тұрақтысы: k = 1.38×10⁻²³ Дж/К Газ тұрақтысы: R = 8.314 Дж/(моль·К) Авогадро саны: N_A = 6.022×10²³ молекула/моль', 3, 2, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '1: Біре молекуланың T = 300 K температурадағы орташа кинетикалық энергясын табыңыз (молекуланың бір ғана трансляциялық удовольствие бар деп есептеңіз).', 1, 3, '["Орташа кинетикалық энергия: ⟨E⟩ = (3/2) k T = (3/2)·1.38e-23·300 = 6.210e-21 Дж.","6.210e-21 Дж ≈ 6.210e-21 Дж."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '2: Молекулалар газында температура 273 K-дан 546 K-қа дейін көтерілді. Орташа кинетикалық энергия қалай өзгереді?', 1, 4, '["Орташа кинетикалық энергия ∝ T. T екі есеге артқандықтан (273→546), орташа кинетикалық энергия да екі есеге артады."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '3: Молекулаға тән жылдамдықтың (rms) анықтамасы: v_rms = √(3kT/m). Егер молекуланың массасы m = 4.65×10⁻²⁶ кг (азот молекуласы N₂ үшін шамамен), T = 300 K болса, v_rms табыңыз.', 1, 5, '["v_rms = √(3kT/m) = √(3·1.38e-23·300 / 4.65e-26) = 516.81 м/с."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '4: Молекуланың трансляциялық энергиясының (орташа) формуласы қандай? Және 1 мол газдың орташа кинетикалық энергиясын R мен T арқылы өрнектеңіз.', 1, 6, '["Орташа трансляциялық энергия бір молекула үшін ⟨E⟩ = (3/2) k T. 1 мол (N_A молекула) үшін U = N_A·⟨E⟩ = N_A·(3/2) k T = (3/2) R T."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '5: Температура 0 °C (273 K) болғанда бір мол идеал газының ішкі энергиясы (тек трансляциялық қозғалыс қабылдансын) қандай болады?', 1, 7, '["U = (3/2) R T = (3/2)·8.314·273 = 3404.58 Дж/моль."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '6. Орташа деңгейі --- Есеп 6: Сутегі молекуласының (H₂) бір молекуласының орташа кинетикалық энергиясын T = 500 K кезінде есептеңіз. H₂ массасы ≈ 3.32×10⁻²⁷ кг. Қосымша: осы молекула үшін v_rms табыңыз.', 2, 8, '["⟨E⟩ = (3/2) k T = (3/2)·1.38e-23·500 = 1.035e-20 Дж.","v_rms = √(3kT/m) = √(3·1.38e-23·500 / 3.32e-27) = 2496.99 м/с.","7.  Орташа деңгейі --- Есеп 7:","1,00 моль аргон (арнайы атомарлық) газының ішкі энергиясын T = 400 K кезінде табыңыз (аргон тек трансляциялық қозғалысқа ие --- 3/2 RT).","U = (3/2) R T = (3/2)·8.314·400 = 4988.40 Дж/моль.","8.  Орташа деңгейі --- Есеп 8:","Молекуланың внутрішньо ротациялық деңгейіне қатысты: Кіші молекулаға (диатомдық) ротациялық орташа энергия = kT. 1 молекула үшін және 1 мол үшін өрнектеп көрсетіңіз.","Ротациялық орташа энергия (классикалық) бір молекула үшін ⟨E_rot⟩ = k T. 1 мол үшін U_rot = N_A k T = R T.","9.  Орташа деңгейі --- Есеп 9:","Екіатомдық газда (бағыттар: трансляция + ротация) бір молекула үшін орташа кинетикалық энергия қандай? (Үздіксіз классикалық статистикада)","Екіатомдық газ классикалық жағдайда (тек трансляция+ротация) қосынды энергия: ⟨E⟩ = (3/2)kT (трансляция) + (1)kT (ротация) = (5/2) k T бір молекула үшін.","1 мол үшін U = (5/2) R T.","10. Орташа деңгейі --- Есеп 10:","Температураны T1=300 K-ден T2=600 K-ға өзгертсек, молекуланың ротациялық энергиясы қалай өзгереді, егер ротациялық энергия ∝ T болса?","Ротациялық энергия ∝ T болғандықтан, T екі еселенсе, ротациялық энергия да екі еселенеді."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 12), '11. Күрделі деңгейі --- Есеп 11: Ковалентті байланыс күші бар диатомдық молекуланың негізгі тербеліс жиілігі ν = 6.0×10¹³ Гц деп берілсін. Осы тербеліс үшін кванттық тербелмелі энергия деңгейлері E_n = hν (n + 1/2) формуласы бойынша n=0 және n=1 деңгейлерінің энергияларын есептеңіз (h = 6.626×10⁻³⁴ Дж·с).', 3, 9, '["E_0 = hν(1/2) = 6.626e-34·6.000e+13·0.5 = 1.988e-20 Дж.","E_1 = hν(3/2) = 6.626e-34·6.000e+13·1.5 = 5.963e-20 Дж.","ΔE = E_1 − E_0 = 3.976e-20 Дж = 3.976e-20 Дж = hν.","12. Күрделі деңгейі --- Есеп 12:","Молекулалық спектр: Егер молекуланың бір спектр сызығының энергиясы ΔE = 2.0×10⁻²⁰ Дж болса, оның жиілігін ν табыңыз және толқын ұзындығын λ есептеңіз (c = 3.00×10⁸ м/с).","ν = ΔE / h = 2.000e-20 / 6.626e-34 = 3.018e+13 Гц.","λ = c / ν = 3.000e+08 / 3.018e+13 = 9.939e-06 м.","13. Күрделі деңгейі --- Есеп 13:","Диатомдық молекуланың ротациялық энергия деңгейлері (қатты жерлерде) E_J = (h² / 8π² I) J(J+1). Берілген момент инерциясы I = 1.0×10⁻⁴⁶ кг·м² үшін J=0→1 өтпелігі үшін энергияны есептеңіз.","E(J=0→1) = h²/(4π² I) = (6.626e-34)² / (4·π²·1.000e-46) = 1.112e-22 Дж.","14. Күрделі деңгейі --- Есеп 14:","Бір молекуланың тербелмелі энергиясының алғашқы екі деңгейі арасындағы энергия айырмасы ΔE = hν. Егер ν = 5.0×10¹³ Гц болса, осы ΔE-ді Дж және эВ-те есептеңіз (1 эВ = 1.602×10⁻¹⁹ Дж).","ΔE = hν = 6.626e-34·5.000e+13 = 3.313e-20 Дж = 0.207 эВ.","15. Күрделі деңгейі --- Есеп 15:","Термодинамика: 1,00 моль екіатомдық идеал газды T = 1000 K-ге дейін қыздырғанда (постоянный көлемде) оның ішкі энергия қалай өзгереді? (Үш инвариант: Cv = (5/2) R). ΔU = n Cv ΔT табыңыз.","Cv = (5/2)R = 20.785 Дж/(моль·К).","ΔT = 1000 − 300 = 700 K.","ΔU = n Cv ΔT = 1·20.785·700 = 14549.50 Дж.","Құжат жасалған: 2025-12-10 15:52:14"]', NULL);

