INSERT INTO public.problems (topic_id, problem_text_kz, difficulty, sort_order, solution_steps, expected_answer) VALUES
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Тақырып:Молекулалардың электрондық спектрлері тақырыбы бойынша деңгейлік есептер', 1, 0, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Сутек молекуласы (H₂) электрондық қозу кезінде 10,2 эВ энергия жұтты. Жұтылған фотонның толқын ұзындығын анықтаңыз.', 1, 1, '["λ=$\\frac{hc}{E}$","=(6.63×10⁻³⁴×3×10⁸)/(10.2×1.6×10⁻¹⁹)=1.22×10⁻⁷м=122нм"]', 'λ = 122 нм'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Молекула электрондық деңгеймен бірге тербелмелі деңгейге өтеді. Электрондық энергия айырмасы 3.0 эВ, тербелмелі энергия айырмасы 0.2 эВ. Фотонның толқын ұзындығын табыңыз.', 1, 2, '["λ=$\\frac{hc}{E}$","=(6.63×10⁻³⁴×3×10⁸)/(3.2×1.6×10⁻¹⁹)=3.88×10⁻⁷м=388нм"]', 'λ = 388 нм'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Молекуланың электрондық өтулерінің бірі 400 нм, екіншісі 500 нм. Қай фотонның энергиясы үлкен?', 1, 3, '[]'::jsonb, 'сондықтан 400 нм фотонның энергиясы үлкен.'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Фотон энергиясы 2.48 эВ болса, оның толқын ұзындығын есептеңіз.', 1, 4, '["=(6.63×10⁻³⁴×3×10⁸)/(2.48×1.6×10⁻¹⁹) = 5.0×10⁻⁷ м = 500 нм."]', 'λ =500нм'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Фотон толқын ұзындығы 250 нм болса, энергиясын табыңыз.', 1, 5, '[]'::jsonb, 'E =4.97 эВ.'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Электрондық ауысудың таза энергиясы E=2.60 эВ. Бұл ауысу кезінде молекула қосымша v′=2 тербеліс деңгейіне көтеріледі; бір тербеліс квантінің энергиясы ΔEvib=0.14 эВ .а) Жалпы фотон энергиясын есептеңіз. б) Фотонның толқын ұзындығын (нм) табыңыз.', 2, 6, '["(Ескерту: егер тербеліс энергиясы «қосымша алынған» болса --- фотон энергиясы кемиді; осылайша алдымыздағы есеп сол бағытта орындалды.)б) Джоульге ауыстыру: E=2.32×1.602×10⁻¹⁹=3.7186×10⁻¹⁹ Дж.","λ = $\\frac{hc}{E}$","=1.986×$10^{- 25}$\\\\3.7186×10⁻¹⁹ =534нм"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Спектрден екі сызық табылды: ${\ \lambda}_{1}$=310 нм және ${\ \lambda}_{2}$=315 нм. Энергия айырмасын (эВ) және вейвнамберлік айырманы (см⁻¹) есептеңіз.', 2, 7, '["$\\nu_{1}$=$\\frac{1}{310 \\times 10\\hat{} - 9}$=3.2258×$10^{6}m^{- 1}$= 32258${cm}^{- 1}$","$\\nu_{2}$=$\\frac{1}{315 \\times 10\\hat{} - 9}$=3.1746×$10^{6}m^{- 1}$= 31746${cm}^{- 1}$","2.Δν\\~=32258−31746=512 ${cm}^{- 1}$","3.Энергия айырмасы (Дж): ΔE=hc×(Δνв$м^{- 1}$ )=1.986×$10^{- 25}$×51200=1.017×$10^{- 20}$Дж","4.ЭВ: ΔE=1.017×$10^{- 20}$/1,602×10⁻¹⁹ =0,0635эВ."]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Сызықтың жиілік бойынша ені Δν=8.0×$10^{11}$.Өмір уақыты жуықша τ≈1/Δν Өмір уақытын есептеп, қысқаша түсіндіріңіз.', 2, 8, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Бір молекуланың электрондық ауысуы кезінде таза электрондық энергия E=3.40 эВ. Төменгі күйден v′′=0бастапқы күйге ауысқанда қозу күйінің v′=0және v′=1тербеліс деңгейлеріне сәйкес екі сызық пайда болады. Бір тербеліс квантінің энергиясы ΔE=0.18 эВ а) v′=0 және v′=1 үшін фотон энергияларын (эВ) табыңыз. б) Оларға сәйкес толқын ұзындықтарды (нм) есептеңіз.', 2, 9, '["v′=0: $E_{0}$=Eel−0×ΔEvib=3.40 эВ.","v′=1: $E_{1}$=3.40−1×0.18=3.22 эВ.","б) Энергияны джоульге аудармай-ақ формуланы қолдану арқылы жылдам есептеу үшін мына формулды қолданамыз:","λ(нм)≈1240 эВ⋅нм\\\\E(eV)\\","v′=0:$\\ \\lambda_{0}$ ≈1240/3.40≈364.7 нм.","v′=1:$\\ {\\ \\lambda}_{1}$ ≈1240/3.22≈384.8нм"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Бір молекуланың электрондық негізгі сызығы $\lambda_{0}$=250 нм. Оның бірінші вибрациялық көршісі ${\ \lambda}_{1}$=270 нм. Вейвнамберлік айырманы табыңыз.Осы Δν -ға сәйкес энергияны эВ-мен есептеңіз.Қысқаша түсіндіру: неге ${\ \lambda}_{1}$\>$\lambda_{0}$ ​?', 2, 10, '["ν=$\\frac{10^{7}}{\\lambda нм}$","$\\nu_{0}$​=$\\frac{10^{7}}{250} = 40000{cm}^{- 1}\\$","$\\nu_{1}$=$\\frac{10^{7}}{270} = 37037{cm}^{- 1}\\$","2\\. Айырма: Δν\\~=$\\nu_{0}$ ​−$\\nu_{1}$ ​=40000−37037=2963 ${cm}^{- 1}$","3\\. Энергияны эВ-ке ауыстыру:ΔE≈2963×1.2398×$10^{- 4}$eV≈0.367 эВ"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Қысқа түсініктеме:$\ {\ \lambda}_{1}$ \>$\lambda_{0}$себебі v′=1-ге кеткен тербеліс энергиясы фотонға жетпейді --- фотон аз энергия алып шығады → λ = $\frac{hc}{E}$ бойынша толқын ұзындығы ұзарған (қызылға ығысқан).', 2, 11, '[]'::jsonb, NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Franck--Condon факторлары төмендегідей: FC(0→0)=0.30 FC(0→1)=0.45 FC(0→2)=0.20 Вибрациялық квант энергиясы: hν=0.16эВ Электрондық өту энергиясы: $E_{00}$=3.10эВ Әр үш шыңның (0→0, 0→1, 0→2) толқын ұзындықтарын және салыстырмалы интенсивтілігін анықтаңыз.', 3, 12, '["Толқын ұзындықтары:$\\ \\lambda_{0} = 1240/3.10 = 400.0\\ нм$ ${\\ \\lambda}_{1}$=1240/3.26=380.7 нм ${\\ \\lambda}_{2}$=1240/3.42=362.0 нм Салыстырмалы қарқындылықтар: 0.30 : 0.45 : 0.20 (нормаланған)."]', '400 нм(әлсіз), 381 нм (ең күшті), 362 нм (орташа).'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Берілген электрондық өту: $E_{00}$=2.95эВ hν=0.17 эВ Лазер толқын ұзындығы:λ=405 нм Фотон молекуланы тек электрондық деңгейге ғана емес, v′ = 2 вибрациялық күйіне дейін көтере ала ма?', 3, 13, '["Қажетті энергия: $E_{v'' = 2}$= $E_{00}$+2hν=2.95+0.34=3.29эВ","Салыстыру: 3.062\\<3.293.062 \\< 3.293.062\\<3.29"]', 'Жоқ, лазер v′=2 деңгейін қоздыра алмайды (тек v′=0 маңында ғана қоздырады).'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Молекуланың электрондық негізгі күйінің потенциал қисығы гармоникалық, ал қозған күйінің минимумдық арақашықтығы 0.015 нм оңға ығысқан. Екі күйдің вибрациялық жиілігі бірдей: hν=0.18 эВ Электрондық өтудің вертикал энергиясы (Franck--Condon максимумы):Evert=3.40 эВ. Электрондық минимум→минимум аралығының энергиясы $E_{00}$ табыңдар. (Бір квантқа шамамен 0.5 hν артық энергия кетеді деп қабылдаңдар). $E_{00} -$ге сәйкес λ есептеңдер.', 3, 14, '["0.5hν=0.09 эВ","$E_{00}$=3.40−0.09=3.31 эВ","λ=1240\\\\3.31=374.6 нм"]', '$\ E_{00}$ =3.31 эВ, λ = 374.6 нм'),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Молекуланың электрондық--вибрациялық спектрі зерттеледі. Өлшеу нәтижесінде бірінші вибрациялық өтудің интенсивтілік қатынасы$\ I_{1}$/$I_{0} = \$`<!-- -->`{=html}0.90 екені анықталған. Молекуланың бір вибрациялық квантының энергиясы hν=0.13 эВ. Электрондық өтудің нөлдік--нөлдік деңгейлер арасындағы энергиясы =3.25E\_{00} $E_{00}$= 3.25эВ.Флуоресценция спектрінде эмиссияның максимумы 385 нм толқын ұзындығына келеді.Абсорбция тәжірибесінде оптикалық жол ұзындығы 1.00 см, ал вертикальдық жұту максимумындағы оптикалық тығыздық A=0.55 Ерітіндінің молярлық экстинкция коэффициенті ε=1.0×$10^{4}$ $М^{- 1}{см}^{- 1}$. Табу керек S, Evert және λvert ​, Stokes ығысуы (эВ) және v′=0..3тің нормаланған FC ықтималдықтары.', 3, 15, '["2\\. Evert​≈$E_{00}$+Shν=3.25+0.90×0.13=3.367 eV.","λvert​=1240/3.367≈368.1 нм","3\\. Эмиссия энергиясы Eem=1240/385≈3.221эВ","Stokes: ΔE=Evert−Eem=3.367−3.221=0.146 эВ","4, FC (унормаланбаған) I=S/v′! → v′=0..3:","$I_{0}^{1}$=1, $I_{1}^{1}$=0.90, $I_{2}^{1}$=0.405, $I_{3}^{1}$=0.1215. Жиынтық =2.4265","Нормаланған ықтималдықтар:","$p_{0}$=1/2.4265≈0.412, $p_{1}$≈0.371 ​$p_{2}$≈≈0.167, $p_{3}$≈≈0.050"]', NULL),
  ((SELECT id FROM public.topics WHERE week_number = 15), 'Молекула электрондық өтудің энергиясы: Eel=3.05 эВ. Вибрациялық квант энергиясы: ΔEvib=0.09 эВ.Franck--Condon қатынасы $I_{1}$/$I_{0} = \$=1.1 Эмиссия максимум $\lambda_{em}$=410 нм. параметр S , 0--0, 0--1, 0--2 өтулерге сәйкес толқын ұзындықтарын есептеңдер. Stokes ығысуын (эВ) анықтаңдар.', 3, 16, '["2\\. Энергиялар (v\\''=0..2):","$E_{0}$=$E_{el}$=3.05эВ $E_{1}$=3.05+0.09=3.14 эВ $E_{2}$=3.05+0.18=3.23 эВ","3.Толқын ұзындықтары:","λ=$\\frac{1240}{E}$","$\\lambda_{0}$≈406.6  нм","$\\lambda_{1}$≈395.5 нм","$\\lambda_{2}$≈384.5 нм","4.Stokes ығысуы: Эмиссия энергиясы: $E_{em\\mathbf{}}$=1240/410≈3.024эВ","ΔE=E0−$E_{em\\mathbf{}}$=3.05−3.024=0.026 эВ"]', NULL);

